-- Vipricon ltda - población de datos (PostgreSQL).
-- Ejecutar sobre el esquema VACÍO (01_vipricon_ddl_postgres.sql). Todo va en una transacción: si algo falla, no queda nada.
-- Cantidades: customer 100, contract 50, employ 50, asig_service 1000, attendance 200, app_user 100;
-- libres: type_document 3, nolvelty_type 6, location 100, news_log 150, absence 25, refresh_token 150, admin_invite 8.
-- contract_audit NO se inserta: la llenan los triggers al insertar/actualizar contract (50 'I' + 10 'U').
-- Datos ficticios. Los hashes de app_user son BCrypt (coste 12), uno distinto por usuario; las claves no van aquí.
-- Los ids se insertan explícitos para que las llaves foráneas sean deterministas; al final se ajustan las secuencias.

BEGIN;

-- ==========================================================================
-- type_document (3)
-- ==========================================================================

-- ==========================================================================
-- nolvelty_type (6)
-- ==========================================================================

-- ==========================================================================
-- customer (100)  -- 92 activos y 8 inactivos
-- ==========================================================================

-- ==========================================================================
-- contract (50)  -- dispara contract_audit (acción I); luego 10 UPDATE de end_date (acción U)
-- ==========================================================================

UPDATE contract SET end_date = '2026-10-16' WHERE contract_id = 3;
UPDATE contract SET end_date = '2026-10-13' WHERE contract_id = 4;
UPDATE contract SET end_date = '2026-10-17' WHERE contract_id = 15;
UPDATE contract SET end_date = '2026-10-11' WHERE contract_id = 17;
UPDATE contract SET end_date = '2026-10-11' WHERE contract_id = 22;
UPDATE contract SET end_date = '2026-10-22' WHERE contract_id = 34;
UPDATE contract SET end_date = '2026-10-12' WHERE contract_id = 39;
UPDATE contract SET end_date = '2026-10-21' WHERE contract_id = 44;
UPDATE contract SET end_date = '2026-10-13' WHERE contract_id = 47;
UPDATE contract SET end_date = '2026-10-23' WHERE contract_id = 49;

-- ==========================================================================
-- location (100)  -- 2 sedes por contrato, con coordenadas en el área metropolitana de Cúcuta
-- ==========================================================================

-- ==========================================================================
-- employ (50)  -- 45 activos y 5 inactivos
-- ==========================================================================

-- ==========================================================================
-- absence (25)  -- 22 vigentes y 3 anuladas; los turnos no caen en estos días
-- ==========================================================================

-- ==========================================================================
-- asig_service (1000)  -- 20 turnos por vigilante, sin cruces; pasados = finalizados (0), futuros = vigentes (1)
-- ==========================================================================

-- ==========================================================================
-- attendance (200)  -- marcaciones de turnos ya cumplidos desde el 2026-10-05
-- ==========================================================================

-- ==========================================================================
-- news_log (150)  -- novedades de turnos ya cumplidos
-- ==========================================================================

-- ==========================================================================
-- app_user (100)  -- hashes BCrypt (coste 12) distintos por usuario; las claves en claro NO van en este archivo
-- ==========================================================================

-- ==========================================================================
-- admin_invite (8)  -- 5 canjeados (por los ADMIN 4..8), 1 revocado, 1 vencido, 1 vigente
-- ==========================================================================

-- ==========================================================================
-- refresh_token (150)  -- cadenas de rotación (replaced_by_id) agrupadas por family_id
-- ==========================================================================

-- ==========================================================================
-- Ajuste de secuencias (los ids se insertaron explícitos)
-- ==========================================================================
SELECT setval(pg_get_serial_sequence('type_document', 'id'), (SELECT max(id) FROM type_document));
SELECT setval(pg_get_serial_sequence('customer', 'client_id'), (SELECT max(client_id) FROM customer));
SELECT setval(pg_get_serial_sequence('contract', 'contract_id'), (SELECT max(contract_id) FROM contract));
SELECT setval(pg_get_serial_sequence('employ', 'employ_id'), (SELECT max(employ_id) FROM employ));
SELECT setval(pg_get_serial_sequence('asig_service', 'assignment_id'), (SELECT max(assignment_id) FROM asig_service));
SELECT setval(pg_get_serial_sequence('nolvelty_type', 'id'), (SELECT max(id) FROM nolvelty_type));
SELECT setval(pg_get_serial_sequence('attendance', 'id'), (SELECT max(id) FROM attendance));
SELECT setval(pg_get_serial_sequence('absence', 'id'), (SELECT max(id) FROM absence));
SELECT setval(pg_get_serial_sequence('app_user', 'id'), (SELECT max(id) FROM app_user));
SELECT setval(pg_get_serial_sequence('refresh_token', 'id'), (SELECT max(id) FROM refresh_token));
SELECT setval(pg_get_serial_sequence('admin_invite', 'id'), (SELECT max(id) FROM admin_invite));
SELECT setval('location_id_seq', (SELECT max(location_id) FROM location));
SELECT setval('novelty_id_seq', (SELECT max(novelty_id) FROM news_log));

COMMIT;
